// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Rus, Fransız ve İngiliz edebiyatı klasikleri (kolay).
const ozLiterature10Kolay = <(String, String, List<String>, String)>[
  ('Bir öğretmen, gerçekçi ayrıntılarla doğaüstü ve grotesk öğeleri birleştiren bir Rus yazarı tanıtmak istiyor; örnek olarak bir ilahiyat öğrencisinin üç gece boyunca dirilen bir cadının tabutu başında dua okumak zorunda kaldığı öyküyü seçiyor. Bu öğretmenin seçtiği yazar kimdir?', 'Gogol', ['Turgenyev', 'Gonçarov', 'Lermontov'], 'Söz konusu öykü Gogol\'ün Mirgorod kitabındaki \'Viy\'dir; Gogol gerçekçilik ile fantastik ve grotesk öğeleri harmanlamasıyla tanınır.'),
  ('Krılov\'un bir arabayı birlikte çekmeye çalışan kuğu, turna balığı ve kerevitin hiç yol alamamasını anlatan fablının ana fikri nedir?', 'Ortaklar arasında uyum yoksa iş ilerlemez', ['Güçlü olan sonunda her zaman zayıf olanı ezer ve haklı çıkar', 'Gösteriş meraklısı sonunda gülünç olur', 'Çalışkanlık tembelliği her zaman yener'], 'Kuğu göğe, turna balığı suya, kerevit geriye çeker; fabl, birlik olmayan topluluğun başarısızlığa mahkûm olduğunu anlatır.'),
  ('Suç ve Ceza\'nın sonsözünde Raskolnikov nerededir ve yanında kim vardır?', 'Sibirya\'da kürek cezasındadır ve Sonya onu izleyip yakınına yerleşmiştir', ['Petersburg\'da serbesttir ve Dunya ile yaşar', 'Bir manastıra kapanmıştır ve Porfiri onu orada düzenli olarak ziyaret eder', 'Yurt dışına kaçmıştır ve Razumihin ona eşlik eder'], 'Teslim olan Raskolnikov sekiz yıl kürek cezası alır; Sonya Sibirya\'ya gelir ve romanın sonunda Raskolnikov\'un yeniden doğuşu umudu belirir.'),
  ('Petersburg\'un dört \'beyaz gecesi\' boyunca yalnız bir hayalperestin Nastenka ile tanışmasını anlatan Dostoyevski öyküsü hangisidir?', 'Beyaz Geceler', ['Uysal Bir Kız', 'Netoçka Nezvanova', 'Öteki'], 'Beyaz Geceler\'de anlatıcı Nastenka\'ya âşık olur; ama Nastenka beklediği eski sevgilisi dönünce ona gider.'),
  ('Karamazov Kardeşler\'de babasının mirası ve Gruşenka yüzünden babasıyla çatışan, tutkulu ve dürtüsel kardeş hangisidir?', 'Dmitri', ['İvan', 'Alyoşa', 'Smerdyakov'], 'Dmitri, hem para hem de Gruşenka konusunda babası Fyodor\'la rekabet eder; bu çatışma onu baş şüpheli yapar.'),
  ('Savaş ve Barış\'ın sonsözünde Pierre Bezuhov kiminle evlidir?', 'Nataşa Rostova', ['Hélène Kuragina', 'Marya Bolkonskaya', 'Sonya Rostova'], 'Pierre\'in ilk eşi Hélène ölmüştür; sonsözde Pierre ve Nataşa mutlu bir aile kurmuştur. Marya ise Nikolay Rostov\'la evlenir.'),
  ('Tolstoy\'un \'Bir İnsana Ne Kadar Toprak Gerekir?\' öyküsünün ana fikri nedir?', 'Doymak bilmeyen açgözlülük insanı yok eder; sonunda ona yalnız bir mezar kadar toprak kalır', ['Toprağı en çok çalışan kişi mutlaka zengin olur', 'Köylülerin toprak sahibi olması toplumun en büyük ve çözülemez sorunudur, ama bu sorun Rusya\'ya özgüdür', 'Toprak insanı gurbetteki yalnızlıktan kurtaran tek şeydir'], 'Pahom, gün batımına kadar yürüyebildiği toprağın kendisinin olacağı pazarlıkta fazla uzağa gider ve tükenip ölür; ona ancak bir mezar kadar yer gerekir.'),
  ('Çehov\'un \'Bukalemun\' öyküsünde polis müfettişi Oçumelov\'un köpek hakkındaki yargısını sürekli değiştirmesinin nedeni nedir?', 'Köpeğin sahibinin kim olduğuna ilişkin söylentilerin değişmesi', ['Köpeğin farklı renklere bürünmesi', 'Kalabalığın kendisine para vererek onu ikna etmesi ve olayı kapatmasını istemesi', 'Köpeğin aslında kendisine ait olduğunu anlaması'], 'Köpek bir generalinmiş denince suçlu ısırılan adam olur, sokak köpeği denince köpek öldürülmeli denir; öykü yetkiliye yaranma ikiyüzlülüğünü gösterir.'),
  ('Çehov\'un \'Kederim Kime Anlatayım?\' öyküsünde oğlunun ölümünü kimseye anlatamayan arabacı İona sonunda derdini kime anlatır?', 'Atına', ['Rahibe', 'Yolculardan bir öğrenciye', 'Karısına'], 'Kimse onu dinlemeyince İona gece ahıra gider ve acısını küçük kısrağına anlatır; öykü insanlar arasındaki ilgisizliği yürek burkucu biçimde gösterir.'),
  ('Çehov\'un \'Tıp benim yasal karım, edebiyat ise metresim\' sözü onun yaşamındaki hangi gerçeği yansıtır?', 'Hekimlik mesleğini yazarlıkla birlikte sürdürmesini', ['Yazarlıktan önce bir süre avukatlık yapmasını', 'Tiyatroda oyunculuk ve yönetmenliği birlikte yürütmesini', 'Hem öğretmen hem gazeteci olarak çalışmasını'], 'Çehov Moskova Üniversitesi\'nde tıp okumuş, yaşamı boyunca köylüleri çoğu zaman ücretsiz tedavi etmiştir.'),
  ('Orta Çağ\'ın ünlü aşk öyküsü \'Tristan ile İzolde\'de iki gencin birbirine karşı konulmaz biçimde bağlanmasının nedeni nedir?', 'Yanlışlıkla içtikleri bir aşk iksiri', ['Bir cadının onlara yaptığı ve yalnız ölümle bozulabilecek bir lanet', 'Çocukken birbirine verilmiş sözler', 'Kral Mark\'ın onları evlenmeye zorlaması'], 'İzolde\'nin Kral Mark ile evliliği için hazırlanan iksiri yolda Tristan ile İzolde içer; böylece sadakat ile tutku arasında trajik bir çatışma doğar.'),
  ('Rabelais\'nin \'Gargantua ve Pantagruel\' dizisinin kahramanları nasıl karakterlerdir?', 'Dev baba ile dev oğul', ['İki yetim kardeş ve onları büyüten bir rahip', 'Bir köpek ile sahibi olan gezgin bir şövalye', 'Kılık değiştiren bir kral ile soytarısı'], 'Dev kahramanların aşırı yeme içme ve eğitim serüvenleri, Rabelais\'nin skolastiği, kiliseyi ve dönemin eğitimini kahkahayla eleştirmesine olanak verir.'),
  ('Molière\'in \'Burjuva Soylu\' komedisinde Bay Jourdain, bir hocadan dersler aldıktan sonra hayatı boyunca farkında olmadan neyi yaptığını öğrenip sevinir?', 'Nesir (düzyazı) konuştuğunu', ['Şiir yazdığını ve hiç farkında olmadığını', 'Asil bir dille konuştuğunu ve kibar durduğunu', 'Latince ve Yunanca konuştuğunu'], 'Felsefe hocası ona \'şiir olmayan her şey nesirdir\' deyince Bay Jourdain kırk yıldır nesir konuştuğunu fark eder; bu, soylu görünme özentisini hicveden ünlü bir sahnedir.'),
  ('Molière 1673\'te hangi oyunun dördüncü temsilinde sahnede fenalaşıp kısa süre sonra ölmüştür?', 'Hastalık Hastası', ['Tartuffe', 'Don Juan', 'Cimri'], 'Molière, kendi yazdığı oyunda hasta numarası yapan Argan\'ı oynarken öksürük nöbetine yakalanmış ve aynı gece ölmüştür. Başrolü bu oyunda üstlenmişti.'),
  ('Molière\'in \'Scapin\'in Dolapları\' oyununda Scapin\'in işlevi aşağıdakilerden hangisine en yakındır?', 'Hileleriyle genç âşıkların işini yoluna koyan kurnaz uşak', ['Evlilikleri engelleyen zorba baba', 'Dürüstlüğüyle alay edilen filozof', 'Yanlış anlaşılan gizli müfettiş'], 'Scapin, commedia dell\'arte geleneğinden gelen kurnaz uşak tipidir; yaşlı babaları kandırarak gençlerin evlenmesini sağlar.'),
  ('Molière\'in oyunlarında, özellikle farsa yakın yapıtlarında hangi İtalyan tiyatro geleneğinin izleri görülür?', 'Commedia dell\'arte', ['Opera seria', 'Kabuki', 'Miracle oyunları'], 'Molière, gezgin oyunculuk yıllarında gördüğü commedia dell\'arte\'nin hazır tiplerini, taklitlerini ve hareketli anlatımını oyunlarına taşımıştır.'),
  ('Sefiller\'de Jean Valjean\'ın ruhsal dönüşümünü başlatan, ona gümüş şamdanları armağan eden din adamı kimdir?', 'Piskopos Myriel', ['Abbé Faria', 'Peder Frollo', 'Abbé Pirard'], 'Valjean, geceyi geçirdiği evden gümüş eşyaları çalar; yakalandığında piskopos \'onları ben verdim\' diyerek onu kurtarır ve Valjean\'ın yaşamı değişir.'),
  ('Sefiller\'de 1832 ayaklanması sırasında barikatta mermi toplarken vurulan sokak çocuğu kimdir?', 'Gavroche', ['Marius', 'Enjolras', 'Montparnasse'], 'Thénardier çiftinin çocuğu olan Gavroche, ölmeden önce şarkı söyleyerek ölü askerlerin cephanesini toplar; roman, onu yoksul sokak çocuğunun simgesi yapar.'),
  ('Dumas\'nın \'Üç Silahşörler\' romanında silahşörlerin \'Biri hepimiz için, hepimiz biri için\' sözüyle simgelenen ilkesi nedir?', 'Dayanışma ve arkadaşlık', ['Kralın mutlak itaati', 'Soyluluğun kalıtım yoluyla geçmesi', 'Din savaşlarında tarafsızlık'], 'Athos, Porthos, Aramis ve d\'Artagnan\'ın birbirine bağlılığı roman boyunca öne çıkar; söz sonradan dayanışma sloganına dönüşmüştür.'),
  ('Prosper Mérimée\'nin Bizet\'nin ünlü operasına kaynaklık eden novellası hangisidir?', 'Carmen', ['Colomba', 'Mateo Falcone', 'Lokis'], 'Mérimée\'nin 1845 tarihli Carmen\'i, çingene bir kadın ile asker Don José\'nin trajik öyküsünü anlatır; Bizet 1875\'te operasını yazdı.'),
  ('Théophile Gautier\'nin \'Matmazel de Maupin\' romanının önsözüyle ünlenen sanat anlayışı nedir?', 'Sanat için sanat (l\'art pour l\'art)', ['Toplum için sanat (art social)', 'Halk için sanat (art populaire)', 'Dinî amaçlı sanat (art sacré)'], 'Gautier, sanatın yararlı olma kaygısı taşımaması gerektiğini savundu; bu görüş Parnas şiirinin ve estetik anlayışın temelini oluşturdu.'),
  ('Balzac\'ın \'Eugénie Grandet\' romanında babanın en belirgin özelliği nedir?', 'Cimrilikle servetini artırma tutkusu', ['Dindarlık ve yoğun kilise bağlılığı', 'Kumar bağımlılığı ve sürekli borçlanma', 'Siyasi hırs ve saray yaklaşımı'], 'Eski fıçıcı Grandet, kızını ve eşini parasal çıkar uğruna ezen cimri bir tiptir; romanda para ile aile bağları çatışır.'),
  ('Emma Bovary\'nin hayatına hangi yolla son verdiği anlatılır?', 'Arsenik içerek', ['Seine\'e atlayarak', 'Silahla', 'Kendini asarak'], 'Borç içinde kalan ve sevgililerinden destek göremeyen Emma, arsenik içerek acı bir ölümle ölür.'),
  ('Maupassant\'ın hocası ve edebî yolunu açan yazar kimdir?', 'Gustave Flaubert', ['Émile Zola, Médan grubunun önderi', 'Victor Hugo, romantik şair', 'Alphonse Daudet, Provence yazarı'], 'Flaubert, Maupassant\'a yazı disiplini kazandırdı ve onun ilk öykülerinin gelişmesine yardımcı oldu.'),
  ('Daudet\'nin \'Değirmenimden Mektuplar\' kitabı hangi bölgeyi anlatır?', 'Provence', ['Normandiya', 'Bretagne', 'Alsace'], 'Daudet, Provence\'taki değirmen yaşamını ve yerel tipleri sıcak bir mizahla anlattığı kısa yazılarla tanınır.'),
  ('Stendhal\'den Flaubert\'e uzanan Fransız gerçekçiliğinin romanda getirdiği temel yenilik hangisidir?', 'Gündelik yaşamı ve sıradan insanı ayrıntılı gözlemle işlemesi', ['Efsanevi kahramanları öne çıkarması', 'Yalnızca soyluların anlatılması', 'Ayetlerden alıntı yapması'], 'Gerçekçi roman, yaşadığı çağın toplumunu ve sıradan insanın yaşamını gözleme dayanarak anlatır.'),
  ('Edmond Rostand\'ın \'Cyrano de Bergerac\' kahramanının en belirgin kişilik özelliği nedir?', 'Büyük burnuna karşın kılıç ve söz ustası, onurlu, âşık bir şair', ['Sessiz bir keşiş', 'Kibirli bir kral', 'Hesapçı bir tüccar'], 'Cyrano, çirkinliği yüzünden sevdiğine açılamaz ve yakışıklı Christian adına sevgili Roxane\'a mektuplar yazar.'),
  ('Gide, 1947\'de hangi ödülü almıştır?', 'Nobel Edebiyat Ödülü', ['Goncourt Ödülü', 'Renaudot Ödülü', 'Pulitzer Ödülü'], 'André Gide, 1947 Nobel Edebiyat Ödülü\'nü almış, Fransız edebiyatının önde gelen düşünce adamlarından biri sayılmıştır.'),
